// save updates the row and its edges, in one transaction, and returns it, read
// back, or a `NotFoundError`.
pub fn (b CommentUpdateOne) save() !CommentNode {
	b.exec()!
	return b.graph.comments_by_keys([b.data.row_key])![0]
}

// exec updates the row and its edges, in one transaction, or returns a
// `NotFoundError`.
pub fn (b CommentUpdateOne) exec() ! {
	if !b.graph.client.update_one(b.data)! {
		return NotFoundError{
			table: 'comments'
		}
	}
}

// CommentUpdate builds the update of the `comments` rows that match its conditions,
// and of their edges. Start one with `Graph.comments().update()`.
pub struct CommentUpdate {
	graph Graph
pub:
	data vgraph.MutationData
}

// update starts the update of the rows that match the query's conditions; its
// order, limit and offset don't apply.
pub fn (q CommentQuery) update() CommentUpdate {
	return CommentUpdate{
		graph: q.graph
		data:  vgraph.MutationData{
			op:    .update
			table: 'comments'
			conds: q.query.conds.clone()
		}
	}
}

// where keeps the rows that match every one of `conds`.
pub fn (b CommentUpdate) where(conds ...load.Cond) CommentUpdate {
	return CommentUpdate{
		...b
		data: b.data.with_conds(conds)
	}
}

